"""Map inline manuscript quantities to exact owner-supplied summary cells."""
import argparse, hashlib, json
from pathlib import Path
import pandas as pd

ap=argparse.ArgumentParser(); ap.add_argument('--root',type=Path,default=Path('.')); args=ap.parse_args()
root=args.root; output=Path(__file__).resolve().parent
manifest=[]; macros=[]
def claim(name,path,filters,mean='mean',lo='ci_low',hi='ci_high',digits=4,interval=True):
    path=Path('results')/path; f=root/path; frame=pd.read_csv(f); selected=frame
    for k,v in filters.items(): selected=selected[selected[k]==v]
    if len(selected)!=1: raise ValueError((name,len(selected),filters))
    row=selected.iloc[0]; value=f"{row[mean]:.{digits}f}"
    if interval: value+=f" [{row[lo]:.{digits}f}, {row[hi]:.{digits}f}]"
    macros.append('\\newcommand{\\'+name+'}{'+value+'}')
    manifest.append(dict(macro=name,file=str(path),sha256=hashlib.sha256(f.read_bytes()).hexdigest(),filters=filters,columns=[mean,lo,hi] if interval else [mean],text=value))
base=dict(k=3,ncal=499,scenario='heterogeneous',shift=False,alpha=.1,epsilon=1e-6)
def main(name,method,metric='coverage',**updates):
    filters=base|dict(method=method,metric=metric)|updates
    claim(name,'main_summary/summary.csv',filters)
for name,m in [('NaiveJoint','coord_naive'),('BonfJoint','coord_bonferroni'),('RawJoint','raw_l2'),('GlobalJoint','clr_l2')]: main(name,m)
main('NaiveTen','coord_naive',k=10)
for name,m in [('GlobalLow','clr_l2'),('ScaledLow','clr_scaled'),('GroupLow','clr_mondrian')]: main(name,m,'coverage_g0')
for name,m in [('GlobalHigh','clr_l2'),('ScaledHigh','clr_scaled'),('GroupHigh','clr_mondrian')]: main(name,m,'coverage_g1')
main('ScaledTenHigh','clr_scaled','coverage_g1',k=10)
for name,m in [('GlobalShift','clr_l2'),('GroupShift','clr_mondrian'),('WeightedShift','clr_weighted'),('ScaledShift','clr_scaled')]: main(name,m,shift=True)
main('WeightedShiftHigh','clr_weighted','coverage_g1',shift=True)
for name,m in [('GlobalArea','clr_l2'),('ScaledArea','clr_scaled'),('GroupArea','clr_mondrian'),('RawArea','raw_l2'),('MaxArea','raw_linf')]: main(name,m,'volume_fraction')
main('GroupShiftArea','clr_mondrian','volume_fraction',shift=True); main('WeightedShiftArea','clr_weighted','volume_fraction',shift=True)
for name,a,b,shift in [('ScaledAreaDiff','clr_scaled','clr_l2',False),('GroupAreaDiff','clr_mondrian','clr_l2',False),('WeightedGroupAreaDiff','clr_weighted','clr_mondrian',True)]:
    filters=base|dict(shift=shift,method_a=a,method_b=b,metric='volume_fraction')
    claim(name,'main_summary/paired_contrasts.csv',filters,mean='mean_difference')
claim('GlobalShiftDiff','main_summary/shift_contrasts.csv',dict(k=3,ncal=499,scenario='heterogeneous',alpha=.1,epsilon=1e-6,method='clr_l2',metric='coverage'),mean='mean_shift_minus_iid')
for name,scenario,m in [('BoundaryTransformed','zeros_transformed','clr_l2'),('BoundaryOriginal','zeros_original_clr_diagnostic','clr_l2'),('BoundaryRaw','zeros_original_raw','raw_l2')]:
    claim(name,'boundary_summary/summary.csv',dict(k=10,ncal=499,scenario=scenario,shift=False,alpha=.1,epsilon=1e-8,method=m,metric='coverage'))
claim('BoundaryRate','boundary_summary/zero_prevalence.csv',dict(k=10,metric='boundary_response_rate'))
for name,n in [('CalSdSmall',99),('CalSdLarge',499)]:
    claim(name,'main_summary/diagnostics.csv',dict(k=3,ncal=n,scenario='heterogeneous',shift=False,alpha=.1,epsilon=1e-6,method='clr_l2'),mean='coverage_sd',interval=False)
claim('CalTailSmall','main_summary/diagnostics.csv',dict(k=3,ncal=99,scenario='heterogeneous',shift=False,alpha=.1,epsilon=1e-6,method='clr_l2'),mean='empirical_fraction_below_nominal_minus_05',lo='fraction_below_tolerance_ci_low',hi='fraction_below_tolerance_ci_high')
claim('CalTailLarge','main_summary/diagnostics.csv',dict(k=3,ncal=499,scenario='heterogeneous',shift=False,alpha=.1,epsilon=1e-6,method='clr_l2'),mean='empirical_fraction_below_nominal_minus_05',lo='fraction_below_tolerance_ci_low',hi='fraction_below_tolerance_ci_high')
main('TVJoint','tv')
main('KLJoint','kl_forward'); main('KLHigh','kl_forward','coverage_g1'); main('KLShift','kl_forward',shift=True); main('KLArea','kl_forward','volume_fraction')
claim('KLRawAreaDiff','main_summary/paired_contrasts.csv',base|dict(method_a='kl_forward',method_b='raw_l2',metric='volume_fraction'),mean='mean_difference')
claim('ReplacementDelta','boundary_summary/epsilon_contrasts.csv',dict(k=10,scenario='zeros_transformed',method='clr_l2',epsilon_a=1e-2,epsilon_b=1e-8,metric='coverage'),mean='mean_difference')
claim('RankUniform','rank_checks.csv',dict(ncal=99,alpha=.1,law='uniform'),mean='test_coverage',lo='test_ci_low',hi='test_ci_high')
claim('RankTied','rank_checks.csv',dict(ncal=9,alpha=.1,law='bernoulli'),mean='test_coverage',lo='test_ci_low',hi='test_ci_high')
(output/'claim_values.tex').write_text('% Generated by manuscript/extract_claims.py; source cells in claim_provenance.json.\n'+'\n'.join(macros)+'\n')
(output/'claim_provenance.json').write_text(json.dumps(manifest,indent=2)+'\n')
